/* @autogenerated */
import { Component, input } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TranslocoPipe } from '@jsverse/transloco';
import type { ActionContainerComponent } from './action-container.component';

/** Cabecera de la acción activa: migas de pan de los contenedores anidados y acciones del elemento abierto. */
@Component({
  selector: 'action-host',
  standalone: true,
  imports: [MatButtonModule, MatIconModule, MatMenuModule, MatTooltipModule, TranslocoPipe],
  styleUrl: 'action-host.component.scss',
  template: `
    @let leaf = container().leaf;
    @let breadcrumb = container().breadcrumb;
    @let more = 'common.moreActions' | transloco;
    <nav class="crumbs">
      @for (step of breadcrumb; track $index) {
        @let selected = step.selectionModel.selected();
        @let label = step.display() ? step.display()?.display(selected[0]) : step.current()?.title();
        <button type="button" class="crumb crumb-link" (click)="step.close()">
          @if ($index == 0) {
            <mat-icon class="crumb-back">chevron_left</mat-icon>
          }
          <span class="crumb-text">{{ step.name() }}</span>
        </button>
        <mat-icon class="crumb-sep" aria-hidden="true">chevron_right</mat-icon>
        @if (step.breadcrumActions().length > 0) {
          <button type="button" class="crumb crumb-item" [matTooltip]="more" [matMenuTriggerFor]="breadDialogMenu">
            <span class="crumb-text">{{ label }}</span>
            <mat-icon class="crumb-caret">arrow_drop_down</mat-icon>
          </button>
          <mat-menu #breadDialogMenu="matMenu">
            @for (action of step.breadcrumActions(); track $index) {
              <button
                mat-menu-item
                aria-label="{{ action.label() }}"
                (click)="step.executeAction(action.name, selected)"
                [disabled]="!action.enabled(selected)()"
              >
                @if (action.icon()) {
                  <mat-icon>{{ action.icon() }}</mat-icon>
                }
                {{ action.label() }}
              </button>
            }
          </mat-menu>
        } @else {
          <span class="crumb crumb-item"
            ><span class="crumb-text">{{ label }}</span></span
          >
        }
        <mat-icon class="crumb-sep" aria-hidden="true">chevron_right</mat-icon>
      }
      <button type="button" class="crumb crumb-current" aria-current="page" (click)="leaf.close()">
        @if (breadcrumb.length == 0) {
          <mat-icon class="crumb-back">chevron_left</mat-icon>
        }
        <span class="crumb-text">{{ leaf.name() }}</span>
      </button>
    </nav>
    @for (action of leaf.dialogActions(); track $index) {
      <button
        [matButton]="action.appearance?.() ?? 'tonal'"
        aria-label="{{ action.label() }}"
        [matTooltip]="action.tooltip()"
        (click)="leaf.executeAction(action.name, leaf.selectionModel.selected())"
        [disabled]="!action.enabled(leaf.selectionModel.selected())()"
      >
        @if (action.icon()) {
          <mat-icon>{{ action.icon() }}</mat-icon>
        }
        {{ action.label() }}
      </button>
    }
    @if (leaf.dialogMenu().length > 0) {
      <button mat-icon-button aria-label="{{ more }}" [matTooltip]="more" [matMenuTriggerFor]="theDialogMenu">
        <mat-icon>more_vert</mat-icon>
      </button>
      <mat-menu #theDialogMenu="matMenu">
        @for (action of leaf.dialogMenu(); track $index) {
          <button
            mat-menu-item
            aria-label="{{ action.label() }}"
            (click)="leaf.executeAction(action.name, leaf.selectionModel.selected())"
            [disabled]="!action.enabled(leaf.selectionModel.selected())()"
          >
            @if (action.icon()) {
              <mat-icon>{{ action.icon() }}</mat-icon>
            }
            {{ action.label() }}
          </button>
        }
      </mat-menu>
    }
  `,
})
export class ActionHostComponent {
  readonly container = input.required<ActionContainerComponent>();
}
